import {Activity,AlertCircle,ArrowDownLeft,ArrowLeft,ArrowRight,ArrowUpLeft,BarChart3,BedDouble,CalendarDays,Check,CheckCircle2,ChevronDown,ChevronLeft,Clock3,Download,FileText,HeartPulse,Hospital,LayoutDashboard,LogOut,Menu,MoreHorizontal,Plus,RefreshCw,Search,Settings,ShieldCheck,Stethoscope,Users,UserRound,UserRoundCog, Wrench,X,Bell,MonitorCog,ClipboardList,Building2,DoorOpen,CalendarCheck,TrendingUp,Phone,MapPin,Mail,ArrowUpRight,Filter,Eye,CheckCheck} from 'lucide-react';
