const navItems=[
 {id:'overview',label:'نظرة عامة',icon:LayoutDashboard,roles:['owner','admin','manager','doctor','nurse','receptionist','patient']},
 {id:'patients',label:'المرضى والسجلات',icon:Users,roles:['owner','manager','doctor','nurse','receptionist']},
 {id:'appointments',label:'المواعيد',icon:CalendarDays,roles:['owner','manager','doctor','nurse','receptionist','patient']},
 {id:'rooms',label:'الغرف والأسرّة',icon:BedDouble,roles:['owner','manager','nurse','receptionist']},
 {id:'theatres',label:'غرف العمليات',icon:Hospital,roles:['owner','manager','doctor']},
 {id:'equipment',label:'الأجهزة والمعدات',icon:MonitorCog,roles:['owner','manager','nurse','admin']},
 {id:'staff',label:'الموظفون والورديات',icon:UserRoundCog,roles:['owner','manager','admin']},
 {id:'reports',label:'التقارير والإحصائيات',icon:BarChart3,roles:['owner','manager']},
 {id:'alerts',label:'التنبيهات',icon:Bell,roles:['owner','admin','manager','doctor','nurse','receptionist']},
 {id:'activity',label:'سجل النشاط',icon:ClipboardList,roles:['owner','admin','manager']},
 {id:'settings',label:'الإعدادات',icon:Settings,roles:['owner','admin','manager']}
];
const demoAccounts=[['owner','مالك المستشفى','رؤية شاملة للأداء'],['admin','مسؤول النظام التقني','المستخدمون والإعدادات التقنية'],['manager','الإدارة العليا','التشغيل والتقارير'],['doctor','طبيب','المواعيد والملفات المصرح بها'],['nurse','تمريض','المهام والغرف والأجهزة'],['receptionist','موظف الاستقبال','المرضى وحجوزات المواعيد'],['patient','مريض','المواعيد والملف الشخصي']];
const moneylessData=[{name:'الأحد',appointments:34,patients:22},{name:'الاثنين',appointments:42,patients:28},{name:'الثلاثاء',appointments:38,patients:24},{name:'الأربعاء',appointments:49,patients:32},{name:'الخميس',appointments:44,patients:30},{name:'الجمعة',appointments:20,patients:12},{name:'السبت',appointments:31,patients:18}];
const periodData={today:[{name:'08 ص',value:12},{name:'10 ص',value:19},{name:'12 م',value:15},{name:'02 م',value:21},{name:'04 م',value:9}],week:[{name:'الأحد',value:34},{name:'الاثنين',value:42},{name:'الثلاثاء',value:38},{name:'الأربعاء',value:49},{name:'الخميس',value:44},{name:'الجمعة',value:20},{name:'السبت',value:31}],month:[{name:'1–5',value:110},{name:'6–10',value:132},{name:'11–15',value:145},{name:'16–20',value:128},{name:'21–25',value:154},{name:'26–30',value:92}],year:[{name:'يناير',value:390},{name:'فبراير',value:420},{name:'مارس',value:455},{name:'أبريل',value:430},{name:'مايو',value:470},{name:'يونيو',value:510},{name:'يوليو',value:488},{name:'أغسطس',value:520},{name:'سبتمبر',value:490},{name:'أكتوبر',value:540},{name:'نوفمبر',value:0},{name:'ديسمبر',value:0}]};
const formatNum=n=>new Intl.NumberFormat('ar-SY').format(n);
function Status({value}){return <span className={'status '+statusClass(value)}><i/>{value}</span>}
function Logo({small=false}){return <div className="brand"><div className="brand-mark"><HeartPulse size={small?20:24}/></div>{!small&&<div><strong>مشفى الطب الحديث</strong><span>MODERN MEDICAL HOSPITAL</span></div>}</div>}
function Button({children,kind='primary',icon:Icon,onClick,type='button',disabled=false}){return <button type={type} disabled={disabled} onClick={onClick} className={'btn '+kind}>{Icon&&<Icon size={16}/>}<span>{children}</span></button>}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}
function Modal({title,subtitle,onClose,children}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal"><div className="modal-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" onClick={onClose} aria-label="إغلاق"><X size={19}/></button></div>{children}</div></div>}

export default function App(){
 const [data,setData]=useState(loadState);const [role,setRole]=useState(null);const [page,setPage]=useState('home');const [publicPage,setPublicPage]=useState('home');const [menuOpen,setMenuOpen]=useState(false);const [toast,setToast]=useState('');const [modal,setModal]=useState(null);const [search,setSearch]=useState('');const [filter,setFilter]=useState('الكل');const [period,setPeriod]=useState('week');const skipHistory=useRef(false);const lastRoute=useRef('');
 useEffect(()=>{const onPop=event=>{const route=event.state;if(!route?.hospitalRoute)return;skipHistory.current=true;setRole(route.role??null);setPage(route.page??'home');setPublicPage(route.publicPage??'home');setMenuOpen(false);setModal(null)};window.addEventListener('popstate',onPop);return()=>window.removeEventListener('popstate',onPop)},[]);
 useEffect(()=>{const route={hospitalRoute:true,role,page,publicPage};const key=JSON.stringify(route);if(skipHistory.current){skipHistory.current=false;lastRoute.current=key;return}if(!lastRoute.current){window.history.replaceState(route,'');lastRoute.current=key;return}if(lastRoute.current!==key){window.history.pushState(route,'');lastRoute.current=key}},[role,page,publicPage]);
 useEffect(()=>saveState(data),[data]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(t)}},[toast]);
 const notify=(s)=>setToast(s);const update=(fn)=>setData(prev=>fn(prev));const currentRole=role||'owner';const userName=roles[currentRole].name;
 const nav=navItems.filter(n=>n.roles.includes(currentRole));
 function enter(r){setRole(r);setPage('overview');setPublicPage('home');setMenuOpen(false)}function logout(){setRole(null);setPage('home');setPublicPage('home');setModal(null)}
 if(!role){return <><PublicSite page={publicPage} setPage={setPublicPage} onLogin={()=>setPublicPage('login')} onDemo={enter} notify={notify}/>{toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}</div>}</>}
 return <div className="app-shell" dir="rtl">
  <aside className={'sidebar '+(menuOpen?'open':'')}><div className="sidebar-brand"><Logo/></div><div className="workspace"><div className="workspace-icon"><Hospital size={19}/></div><div><b>إدارة المستشفى</b><small>بيئة تجريبية محلية</small></div><ChevronDown size={15}/></div><div className="nav-caption">القائمة الرئيسية</div><nav className="side-nav">{nav.map(n=><button key={n.id} className={'nav-link '+(page===n.id?'active':'')} onClick={()=>{setPage(n.id);setMenuOpen(false)}}><n.icon size={18}/><span>{n.label}</span>{n.id==='alerts'&&data.alerts.some(a=>!a.read)&&<em>{data.alerts.filter(a=>!a.read).length}</em>}</button>)}</nav><div className="sidebar-bottom"><div className="demo-note"><ShieldCheck size={18}/><div><b>وضع العرض التجريبي</b><span>بيانات وهمية محفوظة محليًا</span></div></div><button className="nav-link" onClick={()=>{const v=resetState();setData(v);notify('تمت إعادة البيانات التجريبية إلى الحالة الأصلية')}}><RefreshCw size={17}/><span>إعادة ضبط البيانات</span></button><button className="nav-link logout" onClick={logout}><LogOut size={17}/><span>تسجيل الخروج</span></button></div></aside>
  <div className="main-wrap"><header className="topbar"><div className="topbar-right"><button className="icon-btn mobile-menu" onClick={()=>setMenuOpen(!menuOpen)}><Menu size={21}/></button><div className="history-controls"><button className="icon-btn" onClick={()=>window.history.back()} aria-label="الصفحة السابقة" title="الصفحة السابقة"><ArrowRight size={17}/></button><button className="icon-btn" onClick={()=>window.history.forward()} aria-label="الصفحة التالية" title="الصفحة التالية"><ArrowLeft size={17}/></button></div><div className="breadcrumb"><span>مشفى الطب الحديث</span><ChevronLeft size={14}/><b>{navItems.find(n=>n.id===page)?.label||'الرئيسية'}</b></div></div><div className="top-actions"><span className="today-label"><span className="live-dot"/> الأحد، ٢٥ أكتوبر ٢٠٢٦</span><button className="icon-btn notification-btn" onClick={()=>setPage('alerts')} aria-label="التنبيهات"><Bell size={19}/>{data.alerts.some(a=>!a.read)&&<i/>}</button><div className="profile-menu"><div className="avatar">{roles[currentRole].initials}</div><div className="profile-info"><b>{userName}</b><span>{roles[currentRole].label}</span></div><ChevronDown size={15}/></div></div></header>
  <main className="content-area"><div className="content-inner" key={`${currentRole}-${page}-${publicPage}`}>{page==='overview'&&<Dashboard role={currentRole} data={data} setPage={setPage} period={period} setPeriod={setPeriod}/>}{page==='patients'&&<Patients data={data} update={update} role={currentRole} notify={notify} search={search} setSearch={setSearch} modal={modal} setModal={setModal} userName={userName}/>}{page==='appointments'&&<Appointments data={data} update={update} role={currentRole} notify={notify} search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} modal={modal} setModal={setModal} userName={userName}/>}{page==='rooms'&&<Rooms data={data} update={update} notify={notify} userName={userName}/>}{page==='theatres'&&<Theatres data={data} update={update} notify={notify} userName={userName}/>}{page==='equipment'&&<Equipment data={data} update={update} notify={notify} userName={userName} search={search} setSearch={setSearch}/>}{page==='staff'&&<Staff data={data} update={update} notify={notify} search={search} setSearch={setSearch}/>}{page==='reports'&&<Reports data={data} period={period} setPeriod={setPeriod}/>}{page==='alerts'&&<Alerts data={data} update={update}/>}{page==='activity'&&<ActivityLog data={data}/>}{page==='settings'&&<SettingsPage data={data} update={update} notify={notify} onReset={()=>{setData(resetState());notify('تمت إعادة ضبط البيانات')}}/>}</div><footer className="app-footer"><span>© 2026 مشفى الطب الحديث — Modern Medical Hospital</span><span><i className="live-dot"/> نسخة تجريبية · لا تستخدم بيانات حقيقية</span></footer></main></div>
  {toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}</div>}{modal&&<GenericModal modal={modal} setModal={setModal} data={data} update={update} role={currentRole} userName={userName} notify={notify}/>}
 </div>
}

function PageHeader({eyebrow,title,description,actions}){return <div className="page-header"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{actions&&<div className="page-actions">{actions}</div>}</div>}
function Metric({label,value,change,icon:Icon,tone='blue',note}){return <div className="metric-card"><div className={'metric-icon '+tone}><Icon size={20}/></div><div className="metric-copy"><span>{label}</span><strong>{value}</strong><small className={change?.startsWith('+')?'positive':''}>{change||note}</small></div>{change&&<div className="metric-spark"><TrendingUp size={16}/></div>}</div>}
function Dashboard({role,data,setPage,period,setPeriod}){
 const today='2026-10-25';const appointmentsToday=data.appointments.filter(a=>a.date===today&&!['ملغى'].includes(a.status));const occupied=data.rooms.reduce((n,r)=>n+r.occupied,0);const beds=data.rooms.reduce((n,r)=>n+r.beds,0);const available=data.equipment.filter(e=>e.status==='متاح').length;
 const title=({owner:'نظرة عامة على المستشفى',admin:'مركز إدارة النظام',manager:'مركز العمليات اليومية',doctor:'مساحة العمل الطبية',nurse:'لوحة المهام التمريضية',receptionist:'لوحة الاستقبال',patient:'مرحبًا بك في بوابتك الصحية'})[role];
 const desc=({owner:'صورة شاملة عن الأداء التشغيلي ومؤشرات المستشفى.',admin:'إدارة الحسابات ومراقبة بيئة النظام التجريبية.',manager:'تابع الأقسام والتنبيهات والموارد التي تحتاج إلى إجراء.',doctor:'مواعيدك القادمة والمرضى المرتبطون بعملك.',nurse:'المهام اليومية وحالة الغرف والمعدات في نطاق عملك.',receptionist:'الوصول السريع إلى المرضى وحجوزات اليوم.',patient:'يمكنك متابعة مواعيدك ومعلوماتك المتاحة من مكان واحد.'})[role];
 return <><PageHeader eyebrow="مركز التحكم / 25 أكتوبر 2026" title={title} description={desc} actions={<><button className="btn secondary" onClick={()=>window.print()}><FileText size={16}/> طباعة الملخص</button>{['owner','manager','receptionist'].includes(role)&&<Button icon={Plus} onClick={()=>setPage(role==='receptionist'?'appointments':'reports')}>{role==='receptionist'?'حجز موعد':'عرض التقارير'}</Button>}</>}/>
 {role==='owner'&&<div className="hero-strip"><div className="hero-orb orb-one"/><div className="hero-orb orb-two"/><div className="hero-copy"><span className="hero-kicker"><span className="live-dot"/> تقرير تشغيلي مباشر · بيانات تجريبية</span><h2>الرعاية تبدأ من<br/><em>إدارة أكثر ذكاءً.</em></h2><p>كل ما تحتاجه لمتابعة حركة المستشفى واتخاذ قرارات تشغيلية أوضح، في مساحة واحدة.</p><button className="hero-link" onClick={()=>setPage('reports')}>استكشف التقارير <ArrowLeft size={16}/></button></div><div className="hero-stats"><div><span>إجمالي المرضى</span><strong>{formatNum(data.patients.length+1240)}</strong><small>ضمن قاعدة البيانات التجريبية</small></div><div><span>إشغال الأسرّة</span><strong>{Math.round(occupied/beds*100)}<small>%</small></strong><div className="progress"><i style={{width:`${occupied/beds*100}%`}}/></div></div><div><span>حالة التشغيل</span><strong className="operational"><i/> مستقر</strong><small>آخر تحديث قبل لحظات</small></div></div></div>}
 {role==='admin'&&<div className="notice-banner"><ShieldCheck size={21}/><div><b>وصول تقني محدود</b><p>هذه اللوحة مخصصة لإدارة الحسابات والإعدادات التقنية. لا تمنح صلاحيات طبية تلقائية.</p></div><button onClick={()=>setPage('settings')}>إعدادات النظام <ArrowLeft size={15}/></button></div>}
 {role==='patient'&&<div className="patient-welcome"><div className="patient-symbol"><HeartPulse size={32}/></div><div><h2>صحتك، في متناول يدك</h2><p>هذه مساحة تجريبية خاصة بالمريض. المعلومات الظاهرة بيانات افتراضية للعرض فقط.</p></div><Button icon={CalendarDays} onClick={()=>setPage('appointments')}>مواعيدي</Button></div>}
  {role==='patient'&&<div className="patient-shortcuts"><button className="patient-shortcut" onClick={()=>setPage('appointments')}><span className="shortcut-icon blue"><CalendarCheck size={20}/></span><span><b>مواعيدي</b><small>تابع المواعيد القادمة والسابقة</small></span><ArrowLeft size={16}/></button><button className="patient-shortcut" onClick={()=>setPage('appointments')}><span className="shortcut-icon mint"><Clock3 size={20}/></span><span><b>إدارة موعدك</b><small>استعرض مواعيدك وخيارات التغيير</small></span><ArrowLeft size={16}/></button><div className="patient-care-note"><div className="care-note-icon"><HeartPulse size={19}/></div><div><b>خطوة صغيرة لصحتك</b><p>احتفظ بمواعيدك وتعليمات الزيارة في مكان واحد. هذه الواجهة تجريبية ولا تستبدل التواصل مع الفريق الطبي.</p></div><span className="care-spark">✦</span></div></div>}
 <div className="section-heading"><div><h2>{role==='doctor'?'ملخص اليوم':role==='nurse'?'ملخص الوردية':role==='receptionist'?'مؤشرات الاستقبال':role==='patient'?'ملخص ملفك':role==='admin'?'حالة النظام':role==='manager'?'مؤشرات التشغيل':'المؤشرات الرئيسية'}</h2><span>آخر تحديث: الآن</span></div>{['owner','manager'].includes(role)&&<select className="period-select" value={period} onChange={e=>setPeriod(e.target.value)}><option value="today">اليوم</option><option value="week">هذا الأسبوع</option><option value="month">هذا الشهر</option><option value="year">هذا العام</option></select>}</div>
 <div className="metrics-grid">{(role==='patient'?[{label:'المواعيد القادمة',value:'2',icon:CalendarDays,tone:'blue',note:'موعدان مجدولان'},{label:'الزيارات السابقة',value:'4',icon:ClipboardList,tone:'violet',note:'في ملفك التجريبي'},{label:'الملف الصحي',value:'متاح',icon:HeartPulse,tone:'amber',note:'بيانات تجريبية فقط'},{label:'الملف الشخصي',value:'مكتمل',icon:UserRound,tone:'green',note:'بيانات تجريبية'}]:role==='doctor'?[{label:'مواعيد اليوم',value:appointmentsToday.filter(a=>a.doctor==='د. يزن الحسن').length,icon:CalendarDays,tone:'blue',note:'بحسب جدول العرض'},{label:'مرضى مرتبطون',value:'12',icon:Users,tone:'violet',note:'نطاق تجريبي'},{label:'ملاحظات معلقة',value:'3',icon:ClipboardList,tone:'amber',note:'تحتاج إلى مراجعة'},{label:'متابعات اليوم',value:'4',icon:Activity,tone:'green',note:'مواعيد مقترحة'}]:role==='nurse'?[{label:'مهام الوردية',value:'8',icon:ClipboardList,tone:'blue',note:'5 مكتملة · 3 معلقة'},{label:'الأسرّة تحت المتابعة',value:occupied,icon:BedDouble,tone:'violet',note:'حسب حالة الغرف'},{label:'تنبيهات القسم',value:'2',icon:Bell,tone:'amber',note:'تحتاج إلى مراجعة'},{label:'الأجهزة المتاحة',value:available,icon:MonitorCog,tone:'green',note:'على مستوى النظام التجريبي'}]:role==='receptionist'?[{label:'مواعيد اليوم',value:appointmentsToday.length,icon:CalendarDays,tone:'blue',note:'جميع العيادات'},{label:'بانتظار الوصول',value:appointmentsToday.filter(a=>a.status==='مجدول'||a.status==='مؤكد').length,icon:Clock3,tone:'amber',note:'قائمة اليوم'},{label:'وصلوا اليوم',value:appointmentsToday.filter(a=>a.status==='وصل المريض').length,icon:CheckCircle2,tone:'green',note:'تم تسجيل الوصول'},{label:'المرضى المسجلون',value:data.patients.length,icon:Users,tone:'violet',note:'قاعدة البيانات التجريبية'}]:role==='admin'?[{label:'حسابات تجريبية',value:'7',icon:Users,tone:'blue',note:'7 أدوار متاحة للعرض'},{label:'سجل النشاط',value:data.activity.length,icon:ClipboardList,tone:'violet',note:'عمليات محلية مسجلة'},{label:'تنبيهات غير مقروءة',value:data.alerts.filter(a=>!a.read).length,icon:Bell,tone:'amber',note:'في النسخة التجريبية'},{label:'حالة التخزين',value:'محلي',icon:ShieldCheck,tone:'green',note:'LocalStorage'}]:[{label:'المرضى المسجلون',value:formatNum(data.patients.length+1240),change:'+8.4% مقارنة بالفترة السابقة',icon:Users,tone:'blue'},{label:'مواعيد اليوم',value:appointmentsToday.length,change:'+5.2% مقارنة بالفترة السابقة',icon:CalendarDays,tone:'violet'},{label:'إشغال الأسرّة',value:Math.round(occupied/beds*100)+'%',change:'+2.1% مقارنة بالفترة السابقة',icon:BedDouble,tone:'green'},{label:'أجهزة متاحة',value:available,change:'من أصل '+data.equipment.length+' أجهزة',icon:MonitorCog,tone:'amber'}]).map((m,i)=><Metric key={i} {...m}/>)}</div>
 <div className={`dashboard-grid ${role==='patient'?'patient-dashboard-grid':''}`}><section className="panel chart-panel"><div className="panel-head"><div><h3>{role==='patient'?'المواعيد القادمة':role==='doctor'?'جدول المواعيد القادم':'حركة المواعيد'}</h3><p>{role==='owner'||role==='manager'?'مؤشر تجريبي يتغير حسب الفترة المحددة':'نظرة سريعة على نشاطك'}</p></div><button className="text-action" onClick={()=>setPage('appointments')}>عرض التفاصيل <ArrowLeft size={15}/></button></div>{['owner','manager'].includes(role)?<><div className="chart-legend"><span><i className="legend-blue"/> المواعيد</span><span><i className="legend-mint"/> المرضى الجدد</span></div><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={period==='today'?periodData.today:period==='week'?moneylessData:period==='month'?periodData.month:periodData.year} margin={{top:10,right:4,left:-22,bottom:0}}><defs><linearGradient id="blueFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#3e8fce" stopOpacity={.2}/><stop offset="100%" stopColor="#3e8fce" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#e9eef3"/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#8796a5'}}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#8796a5'}}/><Tooltip contentStyle={{border:'1px solid #e8edf2',borderRadius:12,fontFamily:'inherit',fontSize:12}}/><Area type="monotone" dataKey="value" name="المواعيد" stroke="#3386c6" strokeWidth={2.5} fill="url(#blueFill)"/><Area type="monotone" dataKey="appointments" name="المواعيد" stroke="#3386c6" strokeWidth={2.5} fill="url(#blueFill)"/><Area type="monotone" dataKey="patients" name="المرضى الجدد" stroke="#42b8a2" strokeWidth={2} fill="transparent"/></AreaChart></ResponsiveContainer></div></>:<div className="upcoming-list">{data.appointments.filter(a=>a.date>='2026-10-25'&&(role!=='doctor'||a.doctor==='د. يزن الحسن')).slice(0,4).map(a=><div className="upcoming-row" key={a.id}><div className="time-chip">{a.time}</div><div className="upcoming-main"><b>{role==='patient'?'موعد عيادة '+a.department:a.patient}</b><span>{a.doctor} · {a.department}</span></div><Status value={a.status}/></div>)}</div>}</section>
 {role!=='patient'&&<section className="panel alert-panel"><div className="panel-head"><div><h3>التنبيهات التشغيلية</h3><p>الأمور التي قد تحتاج إلى متابعة</p></div><button className="round-count" onClick={()=>setPage('alerts')}>{data.alerts.filter(a=>!a.read).length}</button></div><div className="alert-list">{data.alerts.slice(0,4).map(a=><div className="alert-row" key={a.id}><div className={'alert-symbol '+(a.priority==='عالية'?'red':a.priority==='متوسطة'?'orange':'blue')}><AlertCircle size={17}/></div><div className="alert-body"><b>{a.title}</b><span>{a.detail}</span><small>{a.time}</small></div>{!a.read&&<i className="unread-dot"/>}</div>)}</div><button className="full-link" onClick={()=>setPage('alerts')}>عرض جميع التنبيهات <ArrowLeft size={15}/></button></section>}</div>
 {role!=='patient'&&<div className="dashboard-grid lower-grid"><section className="panel"><div className="panel-head"><div><h3>حالة الموارد</h3><p>توزيع الحالات الحالية</p></div><button className="text-action" onClick={()=>setPage('rooms')}>إدارة الغرف <ArrowLeft size={15}/></button></div><div className="resource-stats"><div className="resource-ring"><div className="ring" style={{'--percent':`${Math.round(occupied/beds*100)}%`}}><div><b>{Math.round(occupied/beds*100)}%</b><small>إشغال الأسرّة</small></div></div></div><div className="resource-legend"><div><i className="dot-blue"/><span>أسرّة مشغولة</span><b>{occupied}</b></div><div><i className="dot-light"/><span>أسرّة متاحة</span><b>{beds-occupied}</b></div><div><i className="dot-orange"/><span>غرف تحتاج متابعة</span><b>{data.rooms.filter(r=>r.status==='تحت الصيانة').length}</b></div></div></div></section><section className="panel"><div className="panel-head"><div><h3>آخر النشاطات</h3><p>سجل العمليات التجريبي</p></div><button className="text-action" onClick={()=>setPage('activity')}>السجل الكامل <ArrowLeft size={15}/></button></div><div className="activity-list">{data.activity.slice(0,4).map(a=><div className="activity-row" key={a.id}><div className="activity-avatar"><Activity size={15}/></div><div><b>{a.action}</b><span>{a.user} · {a.target}</span></div><small>{a.time}</small></div>)}</div></section></div>}
 <div className="disclaimer"><AlertCircle size={15}/><span>الأرقام والسجلات المعروضة بيانات تجريبية لأغراض العرض فقط، ولا تمثل بيانات تشغيل حقيقية للمشفى.</span></div></>
}
function Toolbar({search,setSearch,placeholder='ابحث بالاسم أو الرقم...',children}){return <div className="toolbar"><div className="searchbox"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={placeholder}/>{search&&<button onClick={()=>setSearch('')}><X size={14}/></button>}</div>{children}</div>}
function Patients({data,update,role,notify,search,setSearch,modal,setModal,userName}){const [selected,setSelected]=useState(null);const scopedPatients=role==='nurse'?data.patients.filter(p=>['P-1001','P-1002'].includes(p.id)):data.patients;const list=scopedPatients.filter(p=>(p.name+' '+p.id+' '+p.phone+' '+p.department).toLowerCase().includes(search.toLowerCase()));return <><PageHeader eyebrow="إدارة الرعاية" title="المرضى والسجلات" description="ملفات تجريبية مترابطة تجمع بيانات المريض والزيارات السابقة." actions={['owner','manager','receptionist'].includes(role)&&<Button icon={Plus} onClick={()=>setModal({type:'patient'})}>إضافة مريض</Button>}/><div className="mini-summary"><div><Users size={19}/><span>إجمالي الملفات</span><b>{data.patients.length}</b></div><div><Activity size={19}/><span>ملفات نشطة</span><b>{data.patients.filter(p=>p.status==='نشط').length}</b></div><div><CalendarCheck size={19}/><span>زيارات مرتبطة</span><b>{data.appointments.length}</b></div></div><div className="panel table-panel"><div className="table-top"><div><h3>دليل المرضى</h3><p>جميع الأسماء والمعرّفات في هذه الصفحة وهمية</p></div><Toolbar search={search} setSearch={setSearch} placeholder="ابحث عن مريض أو رقم الملف..."/></div><div className="table-scroll"><table><thead><tr><th>المريض</th><th>رقم الملف</th><th>العمر</th><th>القسم</th><th>الحساسية المسجلة</th><th>الزيارات</th><th>الحالة</th><th></th></tr></thead><tbody>{list.map(p=><tr key={p.id}><td><div className="person-cell"><div className="person-avatar">{p.name.slice(0,1)}</div><div><b>{p.name}</b><span>{p.phone}</span></div></div></td><td><span className="code">{p.id}</span></td><td>{p.age} سنة</td><td>{p.department}</td><td>{p.allergies==='—'?'غير مسجل':p.allergies}</td><td>{p.visits}</td><td><Status value={p.status}/></td><td><button className="icon-btn" title="عرض الملف" onClick={()=>setSelected(p)}><Eye size={17}/></button></td></tr>)}</tbody></table>{list.length===0&&<div className="empty-state"><Search size={25}/><b>لا توجد نتائج</b><span>جرّب عبارة بحث أخرى.</span></div>}</div><div className="table-foot">عرض {list.length} من {data.patients.length} ملفات <span>البيانات محفوظة محليًا على هذا المتصفح</span></div></div>{selected&&<Modal title="الملف التجريبي للمريض" subtitle={`${selected.id} · معلومات افتراضية`} onClose={()=>setSelected(null)}><div className="patient-profile"><div className="profile-large-avatar">{selected.name.slice(0,1)}</div><div><h3>{selected.name}</h3><p>{selected.age} سنة · {selected.department}</p><Status value={selected.status}/></div></div><div className="detail-grid"><div><span>رقم الهاتف</span><b>{selected.phone}</b></div><div><span>تاريخ التسجيل</span><b>{selected.joined}</b></div><div><span>الحساسية</span><b>{selected.allergies}</b></div><div><span>الأمراض المزمنة</span><b>{selected.chronic}</b></div></div><h4 className="subsection-title">الزيارات والمواعيد المرتبطة</h4>{data.appointments.filter(a=>a.patientId===selected.id).map(a=><div className="simple-list-row" key={a.id}><CalendarDays size={16}/><span>{a.date} · {a.time} — {a.department}</span><Status value={a.status}/></div>)}<div className="modal-note">السجل للعرض التجريبي فقط. التعديلات الطبية غير متاحة من هذه الواجهة.</div></Modal>}</>}
function Appointments({data,update,role,notify,search,setSearch,filter,setFilter,setModal,userName}){const scopedAppointments=role==='doctor'?data.appointments.filter(a=>a.doctor==='د. يزن الحسن'):role==='patient'?data.appointments.filter(a=>a.patientId==='P-1001'):data.appointments;const list=scopedAppointments.filter(a=>(a.patient+' '+a.doctor+' '+a.id+' '+a.department).toLowerCase().includes(search.toLowerCase())&&(filter==='الكل'||a.status===filter));const changeStatus=(a,status)=>{update(prev=>audit({...prev,appointments:prev.appointments.map(x=>x.id===a.id?{...x,status}:x)},userName,'تغيير حالة موعد',a.id));notify('تم تحديث حالة الموعد')};return <><PageHeader eyebrow="جدولة الرعاية" title="إدارة المواعيد" description="أنشئ المواعيد وعدّلها وتابع حالتها مع التحقق من تعارضات الطبيب." actions={['owner','manager','doctor','receptionist'].includes(role)&&<Button icon={Plus} onClick={()=>setModal({type:'appointment'})}>حجز موعد جديد</Button>}/><div className="metrics-grid compact-metrics"><Metric label="إجمالي المواعيد" value={data.appointments.length} icon={CalendarDays} tone="blue" note="كل الفترات"/><Metric label="مؤكدة أو مجدولة" value={data.appointments.filter(a=>['مؤكد','مجدول'].includes(a.status)).length} icon={Clock3} tone="violet" note="بانتظار الموعد"/><Metric label="مكتملة" value={data.appointments.filter(a=>a.status==='مكتمل').length} icon={CheckCircle2} tone="green" note="زيارات مكتملة"/><Metric label="لم يحضر" value={data.appointments.filter(a=>a.status==='لم يحضر').length} icon={AlertCircle} tone="amber" note="تحتاج متابعة"/></div><div className="panel table-panel"><div className="table-top"><div><h3>جدول المواعيد</h3><p>اختَر الحالة لمتابعة سير الموعد</p></div><Toolbar search={search} setSearch={setSearch} placeholder="اسم المريض، الطبيب أو رقم الموعد"><select className="filter-select" value={filter} onChange={e=>setFilter(e.target.value)}><option>الكل</option>{['مجدول','مؤكد','وصل المريض','قيد المعالجة','مكتمل','ملغى','لم يحضر','يتطلب إعادة الجدولة'].map(s=><option key={s}>{s}</option>)}</select></Toolbar></div><div className="table-scroll"><table><thead><tr><th>رقم الموعد</th><th>المريض</th><th>الطبيب / القسم</th><th>التاريخ</th><th>الوقت</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>{list.map(a=><tr key={a.id}><td><span className="code">{a.id}</span></td><td><b>{a.patient}</b></td><td><div className="stacked"><span>{a.doctor}</span><small>{a.department}</small></div></td><td>{a.date}</td><td><span className="time-text">{a.time}</span></td><td><Status value={a.status}/></td><td>{['مجدول','مؤكد'].includes(a.status)&&role==='receptionist'?<button className="small-action" onClick={()=>changeStatus(a,'وصل المريض')}>تسجيل الوصول</button>:['owner','manager','receptionist'].includes(role)&&!['مكتمل','ملغى','لم يحضر'].includes(a.status)?<button className="icon-btn" title="تغيير الحالة" onClick={()=>setModal({type:'appointmentStatus',appointment:a})}><MoreHorizontal size={18}/></button>:<span className="muted-text">—</span>}</td></tr>)}</tbody></table>{list.length===0&&<div className="empty-state"><CalendarDays size={24}/><b>لا توجد مواعيد مطابقة</b></div>}</div><div className="table-foot">{list.length} موعدًا ظاهرًا <span>مدة الموعد الافتراضية: {data.settings.appointmentDuration} دقيقة · فاصل زمني: {data.settings.buffer} دقائق</span></div></div></>}
function Rooms({data,update,notify,userName}){const [view,setView]=useState('cards');const setStatus=(room,status)=>{if(status==='مشغولة'&&room.occupied===0){notify('لا يمكن وضع الغرفة بحالة مشغولة دون تخصيص سرير.');return}update(p=>audit({...p,rooms:p.rooms.map(r=>r.id===room.id?{...r,status}:r)},userName,'تغيير حالة غرفة',room.id));notify(`تم تحديث حالة الغرفة ${room.id}`)};return <><PageHeader eyebrow="الموارد السريرية" title="الغرف والأسرّة" description="متابعة الإشغال والتوفر والصيانة. تغيّر الحالات ينعكس على المؤشرات مباشرة." actions={<div className="segmented"><button className={view==='cards'?'selected':''} onClick={()=>setView('cards')}>بطاقات</button><button className={view==='table'?'selected':''} onClick={()=>setView('table')}>جدول</button></div>}/><div className="metrics-grid compact-metrics"><Metric label="عدد الغرف" value={data.rooms.length} icon={DoorOpen} tone="blue" note="كل الأقسام"/><Metric label="إجمالي الأسرّة" value={data.rooms.reduce((n,r)=>n+r.beds,0)} icon={BedDouble} tone="violet" note="السعة التجريبية"/><Metric label="أسرّة مشغولة" value={data.rooms.reduce((n,r)=>n+r.occupied,0)} icon={Users} tone="amber" note="حسب التخصيص الحالي"/><Metric label="غرف متاحة" value={data.rooms.filter(r=>r.status==='متاحة').length} icon={CheckCircle2} tone="green" note="جاهزة للتخصيص"/></div>{view==='cards'?<div className="room-grid">{data.rooms.map(r=><div className="room-card" key={r.id}><div className="room-card-top"><div className="room-icon"><BedDouble size={20}/></div><span className="code">غرفة {r.id}</span><button className="icon-btn" onClick={()=>{const next=prompt('اكتب الحالة الجديدة: متاحة، مشغولة، مشغولة جزئياً، محجوزة، تحت الصيانة، غير متاحة',r.status);if(next&&['متاحة','مشغولة','مشغولة جزئياً','محجوزة','تحت الصيانة','غير متاحة'].includes(next))setStatus(r,next);else if(next)notify('الحالة المدخلة غير معتمدة')}}><MoreHorizontal size={18}/></button></div><h3>{r.type}</h3><p>{r.department}</p><Status value={r.status}/><div className="bed-progress"><div><span>الأسرّة المشغولة</span><b>{r.occupied} / {r.beds}</b></div><div className="progress"><i style={{width:`${r.occupied/r.beds*100}%`}}/></div></div><div className="room-actions"><button disabled={r.occupied>=r.beds||!['متاحة','مشغولة جزئياً'].includes(r.status)} onClick={()=>{const occupied=r.occupied+1;update(p=>audit({...p,rooms:p.rooms.map(x=>x.id===r.id?{...x,occupied,status:occupied===x.beds?'مشغولة':'مشغولة جزئياً'}:x)},userName,'تخصيص سرير',r.id));notify(`تم تخصيص سرير في الغرفة ${r.id}`)}}>تخصيص سرير</button><button disabled={r.occupied<=0} onClick={()=>{const occupied=r.occupied-1;update(p=>audit({...p,rooms:p.rooms.map(x=>x.id===r.id?{...x,occupied,status:occupied===0?'متاحة':'مشغولة جزئياً'}:x)},userName,'إخلاء سرير',r.id));notify(`تم تحديث إشغال الغرفة ${r.id}`)}}>إخلاء سرير</button></div></div>)}</div>:<div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>الغرفة</th><th>النوع</th><th>القسم</th><th>الأسرّة</th><th>المشغولة</th><th>المتاحة</th><th>الحالة</th></tr></thead><tbody>{data.rooms.map(r=><tr key={r.id}><td>{r.id}</td><td>{r.type}</td><td>{r.department}</td><td>{r.beds}</td><td>{r.occupied}</td><td>{r.beds-r.occupied}</td><td><Status value={r.status}/></td></tr>)}</tbody></table></div></div>}<div className="disclaimer"><AlertCircle size={15}/> حالات الغرف والأسرّة تجريبية. لا يُسمح بتخصيص سرير لغرفة تحت الصيانة أو غير متاحة.</div></>}
function Theatres({data,update,notify,userName}){const [booking,setBooking]=useState(false);return <><PageHeader eyebrow="التشغيل الجراحي" title="غرف العمليات" description="متابعة جاهزية الغرف وحجوزات الفرق وحالة التنظيف والتعقيم." actions={<Button icon={Plus} onClick={()=>setBooking(true)}>حجز غرفة عمليات</Button>}/><div className="metrics-grid compact-metrics"><Metric label="غرف العمليات" value={data.theatres.length} icon={Hospital} tone="blue" note="وحدات تجريبية"/><Metric label="متاحة الآن" value={data.theatres.filter(r=>r.status==='متاحة').length} icon={CheckCircle2} tone="green" note="جاهزة للحجز"/><Metric label="محجوزة" value={data.theatres.filter(r=>r.status==='محجوزة').length} icon={CalendarDays} tone="violet" note="ضمن الجدول التجريبي"/><Metric label="تحتاج تجهيزًا" value={data.theatres.filter(r=>['تنظيف وتعقيم','تحت الصيانة','قيد الاستخدام'].includes(r.status)).length} icon={Wrench} tone="amber" note="قبل إعادة الإتاحة"/></div><div className="theatre-grid">{data.theatres.map(t=><div className="theatre-card" key={t.id}><div className="theatre-top"><div className="theatre-icon"><Hospital size={23}/></div><span className="code">{t.id}</span></div><h3>{t.type}</h3><Status value={t.status}/><div className="theatre-details"><div><span>الحجز القادم</span><b>{t.next}</b></div><div><span>الفريق الطبي</span><b>{t.team}</b></div></div><div className="theatre-actions"><button onClick={()=>{const next=prompt('الحالة الجديدة: متاحة، محجوزة، قيد الاستخدام، تنظيف وتعقيم، تحت الصيانة، غير متاحة',t.status);if(next&&['متاحة','محجوزة','قيد الاستخدام','تنظيف وتعقيم','تحت الصيانة','غير متاحة'].includes(next)){update(p=>audit({...p,theatres:p.theatres.map(x=>x.id===t.id?{...x,status:next}:x)},userName,'تحديث حالة غرفة عمليات',t.id));notify('تم تحديث حالة غرفة العمليات')}}}>تحديث الحالة</button></div></div>)}</div>{booking&&<Modal title="حجز غرفة عمليات" subtitle="نموذج حجز تجريبي مع التحقق من توفر الغرفة" onClose={()=>setBooking(false)}><form className="form-grid" onSubmit={e=>{e.preventDefault();const fd=new FormData(e.currentTarget),id=fd.get('room'),team=fd.get('team'),date=fd.get('date'),time=fd.get('time');const room=data.theatres.find(x=>x.id===id);if(!room||room.status!=='متاحة'){notify('تعذر الحجز: الغرفة المختارة غير متاحة حاليًا.');return}update(p=>audit({...p,theatres:p.theatres.map(x=>x.id===id?{...x,status:'محجوزة',next:`${date} · ${time}`,team}:x)},userName,'حجز غرفة عمليات',id));setBooking(false);notify('تم حجز غرفة العمليات بنجاح') }}><Field label="غرفة العمليات"><select name="room" required>{data.theatres.map(t=><option key={t.id} value={t.id} disabled={t.status!=='متاحة'}>{t.id} — {t.type} ({t.status})</option>)}</select></Field><Field label="الفريق الطبي"><input name="team" required placeholder="فريق الجراحة"/></Field><Field label="التاريخ"><input type="date" name="date" min="2026-10-25" required/></Field><Field label="وقت البدء"><input type="time" name="time" required/></Field><div className="form-actions"><Button kind="secondary" onClick={()=>setBooking(false)}>إلغاء</Button><Button type="submit">تأكيد الحجز</Button></div></form></Modal>}</>}
function Equipment({data,update,notify,userName,search,setSearch}){const list=data.equipment.filter(e=>(e.name+' '+e.id+' '+e.department).toLowerCase().includes(search.toLowerCase()));const act=(item,status)=>{if(item.status===status)return;update(p=>audit({...p,equipment:p.equipment.map(e=>e.id===item.id?{...e,status}:e)},userName,status==='تحت الصيانة'?'تسجيل صيانة جهاز':status==='قيد الاستخدام'?'تسجيل استخدام جهاز':'إتاحة جهاز',item.id));notify(`تم تحديث حالة ${item.id}`)};return <><PageHeader eyebrow="الأصول الطبية" title="الأجهزة والمعدات" description="تتبّع حالة كل جهاز وسجّل الاستخدام أو الصيانة ضمن البيانات التجريبية."/><div className="metrics-grid compact-metrics"><Metric label="إجمالي الأجهزة" value={data.equipment.length} icon={MonitorCog} tone="blue" note="وحدات مفردة"/><Metric label="متاحة" value={data.equipment.filter(e=>e.status==='متاح').length} icon={CheckCircle2} tone="green" note="جاهزة للاستخدام"/><Metric label="قيد الاستخدام" value={data.equipment.filter(e=>e.status==='قيد الاستخدام').length} icon={Activity} tone="violet" note="حالة حالية"/><Metric label="تحتاج متابعة" value={data.equipment.filter(e=>['تحت الصيانة','خارج الخدمة'].includes(e.status)).length} icon={Wrench} tone="amber" note="صيانة أو توقف"/></div><div className="panel table-panel"><div className="table-top"><div><h3>سجل الأجهزة</h3><p>اختر الإجراء لتحديث حالة الجهاز</p></div><Toolbar search={search} setSearch={setSearch} placeholder="ابحث عن جهاز أو رمز أو قسم..."/></div><div className="table-scroll"><table><thead><tr><th>الجهاز</th><th>الرمز</th><th>الفئة</th><th>القسم</th><th>الحالة</th><th>الصيانة القادمة</th><th>الإجراءات</th></tr></thead><tbody>{list.map(e=><tr key={e.id}><td><div className="device-cell"><div className="device-icon"><MonitorCog size={18}/></div><b>{e.name}</b></div></td><td><span className="code">{e.id}</span></td><td>{e.category}</td><td>{e.department}</td><td><Status value={e.status}/></td><td>{e.maintenance}</td><td><div className="inline-actions"><button disabled={e.status!=='متاح'} onClick={()=>act(e,'قيد الاستخدام')}>استخدام</button><button disabled={e.status==='تحت الصيانة'} onClick={()=>act(e,'تحت الصيانة')}>صيانة</button><button disabled={!['قيد الاستخدام','تحت الصيانة'].includes(e.status)} onClick={()=>act(e,'متاح')}>إتاحة</button></div></td></tr>)}</tbody></table>{list.length===0&&<div className="empty-state">لا توجد أجهزة مطابقة.</div>}</div></div><div className="disclaimer"><AlertCircle size={15}/> يمنع تسجيل استخدام جهاز خارج الخدمة أو قيد الصيانة. الحالة تتحدث فورًا وتُحفظ محليًا.</div></>}
function Staff({data,update,notify,search,setSearch}){const list=data.staff.filter(s=>(s.name+' '+s.id+' '+s.department+' '+s.title).toLowerCase().includes(search.toLowerCase()));return <><PageHeader eyebrow="رأس المال البشري" title="الموظفون والورديات" description="دليل وظيفي تجريبي يوضح اختلاف الملفات بحسب الدور والقسم." actions={<Button icon={Plus} onClick={()=>notify('للعرض: إضافة موظف جديد غير مفعّلة في هذه النسخة. يمكن إدارة بيانات الموظفين التجريبية الحالية.')} >إضافة موظف</Button>}/><div className="metrics-grid compact-metrics"><Metric label="الموظفون" value={data.staff.length} icon={Users} tone="blue" note="سجلات تجريبية"/><Metric label="الأطباء" value={data.staff.filter(s=>s.role==='doctor').length} icon={Stethoscope} tone="violet" note="كوادر طبية"/><Metric label="التمريض" value={data.staff.filter(s=>s.role==='nurse').length} icon={HeartPulse} tone="green" note="كوادر تمريضية"/><Metric label="ورديات تحتاج تغطية" value={data.shifts.filter(s=>s.staff<s.needed).length} icon={Clock3} tone="amber" note="وفق الإعداد التجريبي"/></div><div className="panel table-panel"><div className="table-top"><div><h3>دليل الموظفين</h3><p>الملفات لا تمثل أشخاصًا حقيقيين</p></div><Toolbar search={search} setSearch={setSearch} placeholder="اسم الموظف أو القسم..."/></div><div className="table-scroll"><table><thead><tr><th>الموظف</th><th>الرقم الوظيفي</th><th>المسمى</th><th>القسم</th><th>الوردية</th><th>الحالة</th></tr></thead><tbody>{list.map(s=><tr key={s.id}><td><div className="person-cell"><div className="person-avatar">{s.name.slice(0,1)}</div><div><b>{s.name}</b><span>{s.phone}</span></div></div></td><td><span className="code">{s.id}</span></td><td>{s.title}</td><td>{s.department}</td><td>{s.shift}</td><td><Status value="نشط"/></td></tr>)}</tbody></table></div></div><div className="panel shifts-panel"><div className="panel-head"><div><h3>تغطية الورديات</h3><p>العدد الحالي مقابل الاحتياج التجريبي</p></div><Clock3 size={19}/></div>{data.shifts.map(s=><div className="shift-row" key={s.id}><div><b>{s.name}</b><span>{s.time} · {s.department}</span></div><div className="shift-bar"><div className="progress"><i className={s.staff<s.needed?'needs-help':''} style={{width:`${Math.min(100,s.staff/s.needed*100)}%`}}/></div><span>{s.staff} / {s.needed}</span></div>{s.staff<s.needed&&<span className="shift-warning">نقص تغطية</span>}</div>)}</div></>}
function Reports({data,period,setPeriod}){const periodLabel={today:'اليوم',week:'هذا الأسبوع',month:'هذا الشهر',year:'هذا العام'}[period];const appts=data.appointments.filter(a=>period==='today'?a.date==='2026-10-25':period==='week'?a.date>='2026-10-19'&&a.date<='2026-10-25':period==='month'?a.date.startsWith('2026-10'):a.date.startsWith('2026'));const completed=appts.filter(a=>a.status==='مكتمل').length;const pie=[{name:'مكتمل',value:data.appointments.filter(a=>a.status==='مكتمل').length},{name:'مجدول/مؤكد',value:data.appointments.filter(a=>['مجدول','مؤكد'].includes(a.status)).length},{name:'ملغى/لم يحضر',value:data.appointments.filter(a=>['ملغى','لم يحضر'].includes(a.status)).length}];const colors=['#3e8fce','#42b8a2','#e7a35b'];return <><PageHeader eyebrow="التحليلات والتقارير" title="التقارير والإحصائيات" description="تتغير المؤشرات حسب الفترة المختارة، وتُحسب من السجلات التجريبية الحالية." actions={<><select className="period-select" value={period} onChange={e=>setPeriod(e.target.value)}><option value="today">اليوم</option><option value="week">هذا الأسبوع</option><option value="month">هذا الشهر</option><option value="year">هذا العام</option></select><Button kind="secondary" icon={Download} onClick={()=>{const rows=[['رقم الموعد','المريض','الطبيب','القسم','التاريخ','الوقت','الحالة'],...appts.map(a=>[a.id,a.patient,a.doctor,a.department,a.date,a.time,a.status])];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='modern-hospital-appointments.csv';a.click();URL.revokeObjectURL(url)}}>تصدير CSV</Button></>}/><div className="report-period"><CalendarDays size={18}/><div><b>ملخص الفترة: {periodLabel}</b><span>البيانات متغيرة وفق السجلات التجريبية الحالية وتواريخها.</span></div></div><div className="metrics-grid"><Metric label="مواعيد ضمن الفترة" value={appts.length} icon={CalendarDays} tone="blue" note={periodLabel}/><Metric label="مواعيد مكتملة" value={completed} icon={CheckCircle2} tone="green" note="من السجلات الموجودة"/><Metric label="إشغال الأسرّة" value={Math.round(data.rooms.reduce((n,r)=>n+r.occupied,0)/data.rooms.reduce((n,r)=>n+r.beds,0)*100)+'%'} icon={BedDouble} tone="violet" note="الحالة الحالية"/><Metric label="طلبات صيانة / توقف" value={data.equipment.filter(e=>['تحت الصيانة','خارج الخدمة'].includes(e.status)).length} icon={Wrench} tone="amber" note="حالة الأجهزة الحالية"/></div><div className="dashboard-grid"><section className="panel chart-panel"><div className="panel-head"><div><h3>حركة المواعيد</h3><p>حجم النشاط عبر {periodLabel}</p></div><BarChart3 size={19}/></div><div className="chart-area tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={period==='today'?periodData.today:period==='week'?moneylessData:period==='month'?periodData.month:periodData.year} margin={{top:12,right:0,left:-20,bottom:0}}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#e9eef3"/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#8796a5'}}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:11,fill:'#8796a5'}}/><Tooltip contentStyle={{borderRadius:12,fontFamily:'inherit',fontSize:12}}/><Bar dataKey="value" name="عدد المواعيد" fill="#438fca" radius={[5,5,0,0]} maxBarSize={36}/></BarChart></ResponsiveContainer></div></section><section className="panel"><div className="panel-head"><div><h3>توزيع حالات المواعيد</h3><p>توزيع إجمالي السجلات الحالية</p></div></div><div className="pie-area"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pie} dataKey="value" nameKey="name" innerRadius={58} outerRadius={82} paddingAngle={4} stroke="none">{pie.map((p,i)=><Cell key={p.name} fill={colors[i]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div className="pie-center"><b>{data.appointments.length}</b><span>موعدًا</span></div></div><div className="pie-legend">{pie.map((p,i)=><div key={p.name}><i style={{background:colors[i]}}/><span>{p.name}</span><b>{p.value}</b></div>)}</div></section></div><div className="panel table-panel"><div className="table-top"><div><h3>تقرير المواعيد التفصيلي</h3><p>{appts.length} سجلات ضمن الفترة المحددة</p></div></div><div className="table-scroll"><table><thead><tr><th>رقم الموعد</th><th>المريض</th><th>الطبيب</th><th>القسم</th><th>التاريخ</th><th>الحالة</th></tr></thead><tbody>{appts.map(a=><tr key={a.id}><td><span className="code">{a.id}</span></td><td>{a.patient}</td><td>{a.doctor}</td><td>{a.department}</td><td>{a.date}</td><td><Status value={a.status}/></td></tr>)}</tbody></table></div></div><div className="disclaimer"><AlertCircle size={15}/> تصدير CSV ينشئ ملفًا من بيانات المواعيد التجريبية فقط. لا تتضمن التقارير بيانات مالية.</div></>}
function Alerts({data,update}){return <><PageHeader eyebrow="مركز المتابعة" title="التنبيهات والإشعارات" description="تابع التنبيهات التشغيلية وغيّر حالة القراءة في النسخة التجريبية." actions={<Button kind="secondary" icon={CheckCheck} onClick={()=>update(p=>({...p,alerts:p.alerts.map(a=>({...a,read:true}))}))}>تحديد الكل كمقروء</Button>}/><div className="alert-summary"><div><span>إجمالي التنبيهات</span><b>{data.alerts.length}</b></div><div><span>غير مقروءة</span><b>{data.alerts.filter(a=>!a.read).length}</b></div><div><span>أولوية عالية</span><b>{data.alerts.filter(a=>a.priority==='عالية').length}</b></div></div><div className="alerts-full">{data.alerts.map(a=><div className={'alert-full-row '+(!a.read?'unread':'')} key={a.id}><div className={'alert-symbol '+(a.priority==='عالية'?'red':a.priority==='متوسطة'?'orange':'blue')}><AlertCircle size={20}/></div><div className="alert-body"><div className="alert-title-row"><b>{a.title}</b><span className={'priority '+(a.priority==='عالية'?'high':a.priority==='متوسطة'?'medium':'low')}>{a.priority}</span></div><p>{a.detail}</p><small>{a.type} · {a.time}</small></div><button className="small-action" onClick={()=>update(p=>({...p,alerts:p.alerts.map(x=>x.id===a.id?{...x,read:!x.read}:x)}))}>{a.read?'تحديد كغير مقروء':'تحديد كمقروء'}</button></div>)}</div></>}
function ActivityLog({data}){return <><PageHeader eyebrow="الحوكمة والشفافية" title="سجل النشاط" description="سجل محلي للعمليات المهمة التي تمت من الواجهة التجريبية."/><div className="notice-banner"><ShieldCheck size={22}/><div><b>سجل توضيحي فقط</b><p>هذا السجل محفوظ في المتصفح ويمكن تعديله محليًا. لا يمثل سجل تدقيق خادميًا غير قابل للتغيير.</p></div></div><div className="panel table-panel"><div className="table-top"><div><h3>آخر العمليات</h3><p>{data.activity.length} عملية مسجلة</p></div></div><div className="table-scroll"><table><thead><tr><th>المستخدم</th><th>العملية</th><th>العنصر المتأثر</th><th>التوقيت</th></tr></thead><tbody>{data.activity.map(a=><tr key={a.id}><td><div className="person-cell"><div className="person-avatar"><Activity size={15}/></div><b>{a.user}</b></div></td><td>{a.action}</td><td><span className="code">{a.target}</span></td><td>{a.time}</td></tr>)}</tbody></table></div></div></>}
function SettingsPage({data,update,notify,onReset}){return <><PageHeader eyebrow="تهيئة بيئة العرض" title="الإعدادات" description="إعدادات تشغيل تجريبية. لا توجد خدمة خلفية متصلة في هذه المرحلة."/><div className="settings-grid"><section className="panel settings-card"><div className="settings-card-icon"><CalendarDays size={21}/></div><h3>قواعد المواعيد</h3><p>مدة الموعد الافتراضية والفاصل الزمني بين حجوزات الطبيب.</p><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);update(p=>({...p,settings:{appointmentDuration:Number(f.get('duration')),buffer:Number(f.get('buffer'))}}));notify('تم حفظ إعدادات الجدولة محليًا')}}><Field label="مدة الموعد (دقيقة)"><select name="duration" defaultValue={data.settings.appointmentDuration}><option value="15">15 دقيقة</option><option value="30">30 دقيقة</option><option value="45">45 دقيقة</option><option value="60">60 دقيقة</option></select></Field><Field label="الفاصل بين المواعيد (دقيقة)"><select name="buffer" defaultValue={data.settings.buffer}><option value="0">دون فاصل</option><option value="5">5 دقائق</option><option value="10">10 دقائق</option><option value="15">15 دقيقة</option></select></Field><Button type="submit">حفظ الإعدادات</Button></form></section><section className="panel settings-card"><div className="settings-card-icon"><ShieldCheck size={21}/></div><h3>بيئة العرض التجريبي</h3><p>البيانات محفوظة محليًا في المتصفح ويمكن استعادتها إلى نقطة البداية.</p><div className="setting-info"><span>نوع التخزين</span><b>LocalStorage</b></div><div className="setting-info"><span>الخادم الخلفي</span><b className="not-connected">غير متصل</b></div><div className="setting-info"><span>بيانات حقيقية</span><b>لا</b></div><Button kind="danger" icon={RefreshCw} onClick={()=>{if(confirm('هل تريد إعادة جميع البيانات التجريبية إلى الحالة الأصلية؟'))onReset()}}>إعادة تعيين البيانات</Button></section><section className="panel settings-card"><div className="settings-card-icon"><Users size={21}/></div><h3>الأدوار التجريبية</h3><p>يمكن تجربة الأدوار من خلال تسجيل الخروج والعودة إلى شاشة الدخول.</p>{demoAccounts.map(a=><div className="simple-list-row" key={a[0]}><div className="person-avatar tiny">{roles[a[0]].initials.slice(0,1)}</div><span>{a[1]}</span><small>{roles[a[0]].en}</small></div>)}</section></div></>}
function GenericModal({modal,setModal,data,update,role,userName,notify}){const close=()=>setModal(null);if(modal.type==='appointmentStatus'){const a=modal.appointment;return <Modal title="تحديث حالة الموعد" subtitle={`${a.id} · ${a.patient}`} onClose={close}><div className="status-options">{['مجدول','مؤكد','وصل المريض','قيد المعالجة','مكتمل','ملغى','لم يحضر','يتطلب إعادة الجدولة'].map(s=><button key={s} className={a.status===s?'chosen':''} onClick={()=>{update(p=>audit({...p,appointments:p.appointments.map(x=>x.id===a.id?{...x,status:s}:x)},userName,'تغيير حالة موعد',a.id));close();notify('تم تحديث حالة الموعد')}}><Status value={s}/>{a.status===s&&<Check size={16}/>}</button>)}</div></Modal>}
 if(modal.type==='patient')return <Modal title="إضافة ملف مريض تجريبي" subtitle="الحقول مطلوبة لإنشاء ملف محلي جديد" onClose={close}><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),name=f.get('name').trim(),phone=f.get('phone').trim();if(!name||!phone){notify('يرجى تعبئة الحقول المطلوبة');return}const id='P-'+(1000+Math.max(0,...data.patients.map(p=>Number(p.id.split('-')[1])-1000))+1);const p={id,name,age:Number(f.get('age')||0),phone,department:f.get('department'),allergies:'غير مسجل',chronic:'—',status:'نشط',joined:'2026-10-25',visits:0};update(prev=>audit({...prev,patients:[p,...prev.patients]},userName,'إنشاء ملف مريض',id));close();notify(`تم إنشاء الملف ${id} بنجاح`)}}><Field label="الاسم الكامل"><input name="name" required placeholder="الاسم الكامل"/></Field><Field label="رقم الهاتف التجريبي"><input name="phone" required placeholder="09XX XXX XXX"/></Field><Field label="العمر"><input name="age" type="number" min="0" max="120" placeholder="العمر بالسنوات"/></Field><Field label="القسم"><select name="department"><option>الباطنة</option><option>القلبية</option><option>الجلدية</option><option>العظمية</option><option>الجراحة</option></select></Field><div className="modal-note full-span">يُنشأ ملف تجريبي دون معلومات طبية حقيقية. لا يتصل النموذج بقاعدة بيانات.</div><div className="form-actions"><Button kind="secondary" onClick={close}>إلغاء</Button><Button type="submit">حفظ ملف المريض</Button></div></form></Modal>;
 if(modal.type==='appointment')return <Modal title="حجز موعد جديد" subtitle="تتحقق الواجهة من تعارض مواعيد الطبيب قبل الحفظ" onClose={close}><form className="form-grid" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),patientId=f.get('patientId'),doctor=f.get('doctor'),date=f.get('date'),time=f.get('time'),duration=Number(data.settings.appointmentDuration),patient=data.patients.find(p=>p.id===patientId);if(!patient){notify('يرجى اختيار مريض صالح');return}const active=data.appointments.some(a=>a.patientId===patientId&&a.date>='2026-10-25'&&['مجدول','مؤكد','وصل المريض','قيد المعالجة','يتطلب إعادة الجدولة'].includes(a.status));if(active){notify('لا يمكن الحجز: للمريض موعد مستقبلي نشط بالفعل.');return}const candidate={id:'A-'+(2400+data.appointments.length+1),patientId,patient:patient.name,doctor,department:f.get('department'),date,time,duration,status:'مجدول'};const conflict=appointmentConflict(data.appointments,candidate,null,data.settings.buffer);if(conflict){notify(`تعارض في الجدول: الطبيب لديه موعد ${conflict.id} في ${conflict.time}. اختر وقتًا آخر.`);return}if(date<'2026-10-25'){notify('لا يمكن حجز موعد في تاريخ سابق.');return}update(p=>audit({...p,appointments:[candidate,...p.appointments]},userName,'إنشاء موعد',candidate.id));close();notify(`تم إنشاء الموعد ${candidate.id} بنجاح`)}}><Field label="المريض"><select name="patientId" required><option value="">اختر المريض</option>{data.patients.map(p=><option key={p.id} value={p.id}>{p.name} · {p.id}</option>)}</select></Field><Field label="الطبيب"><select name="doctor" required><option>د. يزن الحسن</option><option>د. سارة ناصر</option></select></Field><Field label="القسم"><select name="department"><option>القلبية</option><option>الباطنة</option><option>الجلدية</option><option>العظمية</option><option>الجراحة</option></select></Field><Field label="التاريخ"><input name="date" type="date" min="2026-10-25" required/></Field><Field label="الوقت"><select name="time" required>{['08:00','08:30','09:00','09:30','10:00','10:30','11:00','11:30','12:00','12:30','13:00','13:30','14:00','14:30','15:00'].map(t=><option key={t}>{t}</option>)}</select></Field><Field label="المدة"><input value={`${data.settings.appointmentDuration} دقيقة`} readOnly/></Field><div className="modal-note full-span">تطبق قواعد العرض التجريبي: لا موعد مستقبلي نشط آخر للمريض، ولا تداخل زمني للطبيب مع الفاصل المحدد.</div><div className="form-actions"><Button kind="secondary" onClick={close}>إلغاء</Button><Button type="submit">تأكيد الحجز</Button></div></form></Modal>;
 return null}

function PublicSite({page,setPage,onLogin,onDemo,notify}){const [mobileNav,setMobileNav]=useState(false);const [booking,setBooking]=useState(false);return <div className="public-site" dir="rtl"><header className="public-header"><button className="public-brand-button" onClick={()=>setPage('home')}><Logo/></button><nav className={mobileNav?'mobile-open':''}><button onClick={()=>setPage('home')}>الرئيسية</button><button onClick={()=>setPage('about')}>من نحن</button><button onClick={()=>setPage('departments')}>الأقسام الطبية</button><button onClick={()=>setPage('doctors')}>الكادر الطبي</button><button onClick={()=>setPage('contact')}>تواصل معنا</button></nav><div className="public-head-actions"><button className="public-login" onClick={onLogin}><UserRound size={16}/> تسجيل الدخول</button><button className="btn" onClick={()=>setBooking(true)}><CalendarDays size={16}/> احجز موعدًا</button></div><button className="icon-btn public-mobile-menu" onClick={()=>setMobileNav(!mobileNav)}><Menu/></button></header>{page==='login'?<LoginPage onDemo={onDemo} onBack={()=>setPage('home')}/>:page==='home'?<><section className="public-hero"><div className="hero-bg"/><div className="public-hero-content"><div className="public-eyebrow"><span/> رعاية صحية برؤية حديثة</div><h1>رعاية تضع<br/><em>الإنسان أولًا.</em></h1><p>في مشفى الطب الحديث، نؤمن أن الرعاية تبدأ بالاهتمام، وتكتمل بالخبرة والعمل بروح الفريق. مساحة طبية تجمع بين الهدوء والتنظيم والاهتمام بالتفاصيل.</p><div className="public-hero-actions"><button className="btn" onClick={()=>setBooking(true)}>طلب موعد <ArrowLeft size={16}/></button><button className="hero-outline" onClick={()=>setPage('departments')}>استكشف الأقسام <ArrowUpRight size={16}/></button></div><div className="public-trust"><div className="trust-icon"><HeartPulse size={19}/></div><div><b>رعاية منظمة، تجربة أكثر وضوحًا</b><span>معلومات عامة عن الخدمات — يرجى تأكيد التوفر مع المستشفى</span></div></div></div><div className="hero-image-caption"><span className="caption-line"/><div><b>بيئة مصممة للراحة</b><small>صورة مرجعية لمرفق طبي حديث، وليست صورة مؤكدة للمشفى</small></div></div></section><section className="public-intro"><div className="intro-copy"><div className="eyebrow">نبذة عن المشفى</div><h2>الاهتمام بالتفاصيل<br/>يصنع فرقًا.</h2></div><div className="intro-text"><p>نسعى إلى تقديم تجربة رعاية صحية واضحة ومحترمة، مع الاهتمام بخصوصية المريض وسهولة الوصول إلى المعلومات وتنظيم رحلة الزيارة.</p><button className="text-action" onClick={()=>setPage('about')}>اكتشف رؤيتنا <ArrowLeft size={16}/></button></div></section><section className="public-departments"><div className="public-section-heading"><div><div className="eyebrow">التخصصات الطبية</div><h2>رعاية متكاملة، تبدأ من احتياجك.</h2></div><button className="text-action" onClick={()=>setPage('departments')}>جميع الأقسام <ArrowLeft size={16}/></button></div><div className="department-cards">{[['القلبية','متابعة صحة القلب والأوعية الدموية',HeartPulse],['الباطنة','تقييم الحالات الطبية العامة والمتابعة',Activity],['العظمية','تقييم ومتابعة مشكلات الجهاز الحركي',Stethoscope],['التصوير الطبي','فحوصات تصويرية وفق التوفر والإحالة',MonitorCog]].map(([t,d,I])=><button className="department-card" key={t} onClick={()=>setPage('departments')}><div><I size={23}/></div><h3>{t}</h3><p>{d}</p><span><ArrowLeft size={16}/></span></button>)}</div><p className="public-disclaimer">الأقسام المذكورة أمثلة تجريبية للعرض، ولا تؤكد توافر خدمة بعينها في المشفى.</p></section><section className="public-cta"><div><div className="eyebrow">خطوتك التالية</div><h2>هل ترغب في تنظيم زيارتك؟</h2><p>أرسل طلب موعد تجريبيًا أو استكشف بوابة المريض.</p></div><div><button className="btn" onClick={()=>setBooking(true)}>طلب موعد <ArrowLeft size={16}/></button><button className="cta-outline" onClick={onLogin}>بوابة المريض <UserRound size={16}/></button></div></section><PublicFooter setPage={setPage}/></>:<><section className="public-subhero"><div className="eyebrow">مشفى الطب الحديث</div><h1>{page==='about'?'رعاية أكثر إنسانية، وتنظيم أكثر وضوحًا':page==='departments'?'الأقسام والتخصصات الطبية':page==='doctors'?'الكادر الطبي': 'تواصل معنا'}</h1><p>{page==='about'?'رؤيتنا هي أن تكون تجربة الرعاية الصحية قائمة على الاحترام والوضوح والعمل المنظم.':page==='departments'?'استكشف الأقسام التوضيحية، وتأكد من الخدمات المتاحة مباشرة مع المشفى.':page==='doctors'?'الأسماء التالية أمثلة افتراضية لتوضيح شكل دليل الكادر وليست أسماء أطباء حقيقيين.':'هذه صفحة تواصل تجريبية؛ لم تُعتمد أرقام أو عناوين اتصال رسمية.'}</p></section><section className="public-subcontent">{page==='about'?<div className="about-grid"><div><div className="intro-icon"><HeartPulse size={30}/></div><h2>الإنسان في مركز الرعاية</h2><p>نطمح إلى توفير تجربة تتسم بالاهتمام والخصوصية، مع تسهيل الوصول إلى المعلومات وتنظيم المواعيد ومسارات الخدمة.</p></div><div><div className="intro-icon"><ShieldCheck size={30}/></div><h2>الثقة والوضوح</h2><p>نعرض المعلومات بوضوح، ونميز بين البيانات المؤكدة والمواد التوضيحية، ولا نقدم وعودًا علاجية غير موثقة.</p></div><div><div className="intro-icon"><Activity size={30}/></div><h2>عمل متكامل</h2><p>تجربة الرعاية الجيدة تتطلب تنسيقًا بين المريض والكوادر والخدمات المساندة.</p></div></div>:page==='departments'?<div className="department-cards expanded">{[['القلبية','متابعة صحة القلب والأوعية الدموية',HeartPulse],['الباطنة','تقييم الحالات الطبية العامة والمتابعة',Activity],['العظمية','تقييم ومتابعة مشكلات الجهاز الحركي',Stethoscope],['الجلدية','تقييم الحالات الجلدية ومتابعتها',UserRound],['الجراحة','معلومات تنظيمية عن الخدمات الجراحية',Hospital],['التصوير الطبي','فحوصات تصويرية وفق التوفر والإحالة',MonitorCog]].map(([t,d,I])=><div className="department-card" key={t}><div><I size={23}/></div><h3>{t}</h3><p>{d}</p></div>)}</div>:page==='doctors'?<div className="doctor-demo-grid">{[['د. يزن الحسن','اختصاصي قلبية — ملف افتراضي'],['د. سارة ناصر','اختصاصية باطنية — ملف افتراضي'],['د. لينا محمود','اختصاصية جلدية — ملف افتراضي']].map(([n,d])=><div className="doctor-demo" key={n}><div className="doctor-placeholder"><UserRound size={38}/></div><h3>{n}</h3><p>{d}</p><span className="status muted"><i/>بيانات تجريبية</span></div>)}</div>:<div className="contact-grid"><div className="contact-card"><MapPin size={23}/><h3>الموقع</h3><p>السويداء، سوريا</p><small>الموقع المذكور حسب بيانات المشروع المقدمة، دون عنوان تفصيلي مؤكد.</small></div><div className="contact-card"><Phone size={23}/><h3>الهاتف</h3><p>يرجى تأكيد رقم التواصل الرسمي</p><small>لم يُدرج رقم هاتف غير موثق.</small></div><div className="contact-card"><Mail size={23}/><h3>رسالة تجريبية</h3><p>يمكنك تجربة نموذج طلب الموعد.</p><Button onClick={()=>setBooking(true)}>فتح نموذج الموعد</Button></div></div>}<button className="back-home" onClick={()=>setPage('home')}><ArrowLeft size={16}/> العودة للرئيسية</button></section><PublicFooter setPage={setPage}/></>}{booking&&<Modal title="طلب موعد تجريبي" subtitle="لن يتم إرسال أي بيانات إلى المستشفى" onClose={()=>setBooking(false)}><form className="form-grid" onSubmit={e=>{e.preventDefault();setBooking(false);notify('تم تسجيل طلب الموعد التجريبي في الواجهة فقط. لم يُرسل إلى المستشفى.')}}><Field label="الاسم"><input required placeholder="اسم المراجع"/></Field><Field label="رقم الهاتف"><input required placeholder="رقم للتجربة فقط"/></Field><Field label="القسم المطلوب"><select><option>القلبية</option><option>الباطنة</option><option>الجلدية</option><option>العظمية</option><option>التصوير الطبي</option></select></Field><Field label="التاريخ المفضل"><input type="date" min="2026-10-25" required/></Field><div className="modal-note full-span">هذا نموذج عرض فقط، ولا يُعد حجزًا فعليًا أو تأكيدًا لتوفر موعد.</div><div className="form-actions"><Button kind="secondary" onClick={()=>setBooking(false)}>إلغاء</Button><Button type="submit">إرسال طلب تجريبي</Button></div></form></Modal>}{/* toast is local to public view */}<PublicToast/> </div>}
function PublicToast(){const [msg,setMsg]=useState('');useEffect(()=>{const fn=e=>setMsg(e.detail);window.addEventListener('mmh-toast',fn);return()=>window.removeEventListener('mmh-toast',fn)},[]);useEffect(()=>{if(msg){const t=setTimeout(()=>setMsg(''),3000);return()=>clearTimeout(t)}},[msg]);return msg?<div className="toast"><CheckCircle2 size={18}/>{msg}</div>:null}
function LoginPage({onDemo,onBack}){const [picked,setPicked]=useState('owner');const [email,setEmail]=useState('');const [password,setPassword]=useState('');return <section className="login-screen"><div className="login-art"><div className="login-art-overlay"/><div className="login-art-copy"><Logo/><div className="eyebrow">MODERN MEDICAL HOSPITAL</div><h1>رعاية حديثة،<br/><em>تجربة أكثر وضوحًا.</em></h1><p>بوابة تجريبية لاستكشاف تجربة المستشفى ونظام الإدارة متعدد الأدوار.</p><div className="login-art-foot"><ShieldCheck size={17}/> بيانات وهمية · لا يوجد اتصال بخادم</div></div></div><div className="login-form-side"><button className="back-home" onClick={onBack}><ArrowLeft size={16}/> العودة للموقع</button><div className="login-form-wrap"><div className="login-form-icon"><ShieldCheck size={24}/></div><div className="eyebrow">مرحبًا بعودتك</div><h2>تسجيل الدخول</h2><p>اختر حسابًا تجريبيًا للانتقال إلى لوحة الدور المناسبة.</p><form onSubmit={e=>{e.preventDefault();onDemo(picked)}}><Field label="البريد الإلكتروني (اختياري)"><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="demo@modernhospital.test"/></Field><Field label="كلمة المرور (للعرض فقط)"><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="أي قيمة للتجربة"/></Field><Field label="اختر الدور التجريبي"><select value={picked} onChange={e=>setPicked(e.target.value)}>{demoAccounts.map(a=><option value={a[0]} key={a[0]}>{a[1]} — {a[2]}</option>)}</select></Field><button className="btn login-submit" type="submit">دخول إلى لوحة التحكم <ArrowLeft size={17}/></button></form><div className="demo-account-box"><b><ShieldCheck size={16}/> تجربة سريعة دون كلمة مرور</b><div className="demo-account-grid">{demoAccounts.map(a=><button className={picked===a[0]?'picked':''} key={a[0]} onClick={()=>setPicked(a[0])}><span>{roles[a[0]].initials}</span><b>{a[1]}</b></button>)}</div></div><small className="login-note">تسجيل الدخول هنا محاكاة واجهة فقط، ولا ينشئ جلسة آمنة أو يتحقق من هوية المستخدم على الخادم.</small></div></div></section>}
function PublicFooter({setPage}){return <footer className="public-footer"><div><Logo/><p>رعاية صحية برؤية حديثة واهتمام بالتفاصيل.</p></div><div className="footer-links"><button onClick={()=>setPage('about')}>من نحن</button><button onClick={()=>setPage('departments')}>الأقسام</button><button onClick={()=>setPage('doctors')}>الكادر الطبي</button><button onClick={()=>setPage('contact')}>التواصل</button></div><span>© 2026 Modern Medical Hospital · بيانات العرض تجريبية</span></footer>}
